CREATE TABLE `admin` (
  `user_id` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `jenis_admin` enum('Editing','Administrasi','Sistem/Database') NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `admin`
--

INSERT INTO `admin` (`user_id`, `password`, `jenis_admin`) VALUES
('AdmDBS1', 'AdmDBS444', 'Sistem/Database'),
('AdmEdit1', 'AdmEdit444', 'Editing'),
('AdmU1', 'AdmU444', 'Administrasi');

--
-- Triggers `admin`
--
DELIMITER $$
CREATE TRIGGER `trg_admin_insert` BEFORE INSERT ON `admin` FOR EACH ROW BEGIN
    IF CHAR_LENGTH(NEW.password) < 6 OR NEW.password NOT REGEXP '[A-Za-z]' OR NEW.password NOT REGEXP '[0-9]' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Password Admin minimal 6 karakter kombinasi huruf & angka.';
    END IF;
END
$$
DELIMITER ;

-- --------------------------------------------------------

--
-- Table structure for table `berita`
--

CREATE TABLE `berita` (
  `id_berita` int(11) NOT NULL,
  `judul_berita` varchar(255) NOT NULL,
  `sub_judul` varchar(255) DEFAULT NULL,
  `konten` text DEFAULT NULL,
  `penulis` varchar(50) NOT NULL,
  `link_url` varchar(255) NOT NULL,
  `created_at` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Triggers `berita`
--
DELIMITER $$
CREATE TRIGGER `trg_berita_halaman_ai` AFTER INSERT ON `berita` FOR EACH ROW BEGIN
    -- Insert otomatis ke tabel halaman saat ada berita baru
    INSERT INTO `halaman` (`nama_halaman`, `slug_url`, `konten_halaman`, `admin_editor`)
    VALUES (CONCAT('Berita - ', NEW.judul_berita), NEW.link_url, NEW.konten, NEW.penulis);
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_berita_halaman_au` AFTER UPDATE ON `berita` FOR EACH ROW BEGIN
    -- Update otomatis di tabel halaman jika berita diedit
    UPDATE `halaman` 
    SET nama_halaman = CONCAT('Berita - ', NEW.judul_berita),
        konten_halaman = NEW.konten,
        admin_editor = NEW.penulis
    WHERE slug_url = OLD.link_url;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_berita_slug_bi` BEFORE INSERT ON `berita` FOR EACH ROW BEGIN
    -- Generate slug otomatis dari judul untuk publikasi baru
    IF NEW.link_url IS NULL OR NEW.link_url = '' THEN
        SET NEW.link_url = TRIM('-' FROM REGEXP_REPLACE(LOWER(NEW.judul_berita), '[^a-z0-9]+', '-'));
    END IF;
END
$$
DELIMITER ;

