--
-- Table structure for table `guest`
--

CREATE TABLE `guest` (
  `id_guest` int(11) NOT NULL,
  `jenis_akun` enum('Tamu umum','Orang tua/Wali Mahasiswa') NOT NULL,
  `nama_lengkap` varchar(100) NOT NULL,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `nim_mahasiswa` bigint(20) DEFAULT NULL,
  `last_login` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Triggers `guest`
--
DELIMITER $$
CREATE TRIGGER `trg_guest_insert` BEFORE INSERT ON `guest` FOR EACH ROW BEGIN
    IF CHAR_LENGTH(NEW.password) < 6 OR NEW.password NOT REGEXP '[A-Za-z]' OR NEW.password NOT REGEXP '[0-9]' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Password Guest minimal 6 karakter kombinasi huruf & angka.';
    END IF;
END
$$
DELIMITER ;

-- --------------------------------------------------------

--
-- Table structure for table `halaman`
--

CREATE TABLE `halaman` (
  `id_halaman` int(11) NOT NULL,
  `nama_halaman` varchar(255) NOT NULL,
  `slug_url` varchar(255) NOT NULL,
  `konten_halaman` text DEFAULT NULL,
  `admin_editor` varchar(50) DEFAULT NULL,
  `terakhir_diupdate` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Table structure for table `kelas_kuliah`
--

CREATE TABLE `kelas_kuliah` (
  `id_kelas` int(11) NOT NULL,
  `kode_mk` varchar(20) NOT NULL,
  `nama_kelas` char(2) NOT NULL,
  `nidn` int(11) NOT NULL,
  `hari` varchar(15) NOT NULL,
  `jam_mulai` time NOT NULL,
  `jam_selesai` time NOT NULL,
  `ruang` varchar(50) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

