--
-- Table structure for table `mahasiswa`
--

CREATE TABLE `mahasiswa` (
  `nim` bigint(20) NOT NULL,
  `nama_mahasiswa` varchar(100) NOT NULL,
  `fakultas` varchar(50) NOT NULL,
  `prodi` varchar(50) NOT NULL,
  `semester` int(11) DEFAULT 1,
  `jalur_masuk` enum('SNBP','SNBT','Mandiri') NOT NULL DEFAULT 'SNBP',
  `tanggal_lahir` date NOT NULL,
  `no_telp` varchar(15) DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `id_guest_wali` int(11) DEFAULT NULL,
  `status_studi` enum('Aktif','Cuti','Lulus','DO') DEFAULT 'Aktif'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `mahasiswa`
--

INSERT INTO `mahasiswa` (`nim`, `nama_mahasiswa`, `fakultas`, `prodi`, `semester`, `jalur_masuk`, `tanggal_lahir`, `no_telp`, `password`, `id_guest_wali`, `status_studi`) VALUES
(441000026001, 'Ayaka Kamisato', 'Fakultas Bisnis & Manajemen', 'Bisnis Digital', 1, 'SNBP', '2006-07-20', '', '20072006', NULL, 'Aktif'),
(441000026002, 'Kaedehara Kazuha', 'Fakultas Sains & Matematika', 'Statistika', 1, 'SNBP', '2006-09-28', '', '28092006', NULL, 'Aktif');

--
-- Triggers `mahasiswa`
--
DELIMITER $$
CREATE TRIGGER `trg_mhs_insert_nim_pass` BEFORE INSERT ON `mahasiswa` FOR EACH ROW BEGIN
    -- Variabel untuk NIM
    DECLARE v_kode_univ VARCHAR(2) DEFAULT '44';
    DECLARE v_jalur VARCHAR(1);
    DECLARE v_fak VARCHAR(2);
    DECLARE v_prodi VARCHAR(2);
    DECLARE v_angkatan VARCHAR(2);
    DECLARE v_absen INT;
    DECLARE v_prefix VARCHAR(9);
    
    -- --- A. LOGIKA GENERATE NIM ---
    
    -- Tentukan Jalur Masuk
    IF NEW.jalur_masuk = 'SNBP' THEN SET v_jalur = '1';
    ELSEIF NEW.jalur_masuk = 'SNBT' THEN SET v_jalur = '2';
    ELSEIF NEW.jalur_masuk = 'Mandiri' THEN SET v_jalur = '3';
    ELSE SET v_jalur = '0'; END IF;

    -- Tentukan Fakultas & Prodi
    IF NEW.fakultas = 'Fakultas Teknologi dan Informatika' THEN
        SET v_fak = '98';
        IF NEW.prodi = 'Informatika' THEN SET v_prodi = '01';
        ELSEIF NEW.prodi = 'Sistem Informasi' THEN SET v_prodi = '02';
        ELSEIF NEW.prodi = 'Data Science' THEN SET v_prodi = '03';
        ELSEIF NEW.prodi = 'Rekayasa Perangkat Lunak' THEN SET v_prodi = '04';
        ELSE SET v_prodi = '00'; END IF;
        
    ELSEIF NEW.fakultas = 'Fakultas Sains dan Matematika' THEN
        SET v_fak = '87';
        IF NEW.prodi = 'Matematika Terapan' THEN SET v_prodi = '05';
        ELSEIF NEW.prodi = 'Fisika Komputasi' THEN SET v_prodi = '06';
        ELSEIF NEW.prodi = 'Statistika' THEN SET v_prodi = '07';
        ELSE SET v_prodi = '00'; END IF;
        
    ELSEIF NEW.fakultas = 'Fakultas Bisnis dan Manajemen' THEN
        SET v_fak = '76';
        IF NEW.prodi = 'Manajemen' THEN SET v_prodi = '08';
        ELSEIF NEW.prodi = 'Akuntansi' THEN SET v_prodi = '09';
        ELSEIF NEW.prodi = 'Bisnis Digital' THEN SET v_prodi = '10';
        ELSE SET v_prodi = '00'; END IF;
        
    ELSEIF NEW.fakultas = 'Fakultas Desain dan Media Kreatif' THEN
        SET v_fak = '65';
        IF NEW.prodi = 'Desain Komunikasi Visual' THEN SET v_prodi = '11';
        ELSEIF NEW.prodi = 'Animasi dan Media Digital' THEN SET v_prodi = '12';
        ELSEIF NEW.prodi = 'Desain Produk' THEN SET v_prodi = '13';
        ELSE SET v_prodi = '00'; END IF;
        
    ELSE
        SET v_fak = '00'; SET v_prodi = '00';
    END IF;

    -- Tentukan Angkatan (2 digit terakhir tahun saat ini)
    SET v_angkatan = RIGHT(YEAR(CURDATE()), 2);

    -- Gabungkan Prefix NIM (KODEUNIV + JALUR + FAK + PRODI + ANGKATAN)
    SET v_prefix = CONCAT(v_kode_univ, v_jalur, v_fak, v_prodi, v_angkatan);

    -- Cari Nomor Absen Terakhir untuk Prefix yang sama, lalu tambah 1
    -- Mengambil 3 digit terakhir dari NIM agar aman menampung ratusan mahasiswa per prodi
    SELECT IFNULL(MAX(CAST(RIGHT(nim, 3) AS UNSIGNED)), 0) + 1 INTO v_absen
    FROM mahasiswa
    WHERE nim LIKE CONCAT(v_prefix, '%');

    -- Terapkan NIM Baru ke data yang sedang di-insert (Format Absen = 3 digit angka)
    -- Jika dari backend di-insert "0" atau NULL, maka akan diganti otomatis
    IF NEW.nim IS NULL OR NEW.nim = 0 THEN
        SET NEW.nim = CAST(CONCAT(v_prefix, LPAD(v_absen, 3, '0')) AS UNSIGNED);
    END IF;


    -- --- B. LOGIKA PASSWORD (BAWAAN) ---
    IF NEW.password IS NULL OR NEW.password = '' THEN
        SET NEW.password = DATE_FORMAT(NEW.tanggal_lahir, '%d%m%Y');
    ELSE
        IF CHAR_LENGTH(NEW.password) < 6 OR NEW.password NOT REGEXP '[A-Za-z]' OR NEW.password NOT REGEXP '[0-9]' THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Password minimal 6 karakter kombinasi huruf & angka.';
        END IF;
    END IF;

END
$$
DELIMITER ;

