  ADD CONSTRAINT `fk_pimpinan_dosen` FOREIGN KEY (`nidn_pejabat`) REFERENCES `dosen` (`nidn`) ON DELETE SET NULL;

DELIMITER $$
--
-- Events
--
CREATE DEFINER=`root`@`localhost` EVENT `evt_hapus_guest_expired` ON SCHEDULE EVERY 1 DAY STARTS '2026-03-08 14:24:26' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    -- Hapus Tamu Umum yang tidak login (atau dibuat) selama lebih dari 6 bulan
    DELETE FROM guest 
    WHERE jenis_akun = 'Tamu umum' 
    AND last_login < DATE_SUB(NOW(), INTERVAL 6 MONTH);

    -- Hapus Wali Mahasiswa jika status mahasiswa sudah Lulus atau DO (Masa studi selesai)
    DELETE g FROM guest g
    JOIN mahasiswa m ON g.nim_mahasiswa = m.nim
    WHERE g.jenis_akun = 'Orang tua/Wali Mahasiswa' 
    AND m.status_studi IN ('Lulus', 'DO');
END$$

DELIMITER ;
COMMIT;

